      const state = computeRouteSession({
        graph: GRAPH, mode: 'accessible', start: room1F1, destination: room1F2,
      });
      expect(state.phase).toBe('ready');
      // Accessible route must use elevator, not stairs
      const pathIds = (state as any).pathResult.nodeIds as string[];
      expect(pathIds).toContain('b1f1-elevator');
      expect(pathIds).toContain('b1f2-elevator');
